import { useEffect, useMemo, useState } from 'react';
import { FocusContext, useFocusable } from '@noriginmedia/norigin-spatial-navigation';
import { type SearchHit } from '@mfp/core';
import { OnScreenKeyboard } from '../components/OnScreenKeyboard.js';
import { GenreChips } from '../components/GenreChips.js';
import { VirtualRow } from '../components/VirtualRow.js';
import { PosterCard } from '../components/PosterCard.js';
import { EmptyState } from '../components/states.js';
import { useRemPx } from '../theme/useRemPx.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useNavigation, voltandoComFoco } from '../nav/navigationStack.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';
import { cssLen } from '../theme/cssMath.js';

/**
 * A última busca, guardada fora do React. Abrir um resultado desmonta esta tela;
 * sem isto, voltar do detalhe devolvia a busca em branco — pior que uma lista no
 * topo, porque não sobra lista nenhuma. O digitado e o confirmado são guardados
 * separados para repor exatamente a tela que o usuário deixou.
 */
let ultimoDigitado = '';
let ultimoBuscado = '';
let ultimosHits: SearchHit[] = [];

export function Search({ listId }: { listId: string }) {
  const rt = useRuntime();
  const push = useNavigation((s) => s.push);
  const voltando = voltandoComFoco();
  const [query, setQuery] = useState(() => (voltando ? ultimoDigitado : ''));
  /** Termo **confirmado** na tecla Buscar — só ele dispara consulta. */
  const [termo, setTermo] = useState(() => (voltando ? ultimoBuscado : ''));
  const [rawHits, setRawHits] = useState<SearchHit[]>(() =>
    voltando ? ultimosHits : [],
  );
  const [buscando, setBuscando] = useState(false);
  /** Aba de tipo (tela 08). `todos` mantém os grupos empilhados. */
  const [aba, setAba] = useState<'todos' | 'vod' | 'series' | 'live'>('todos');
  const active = termo.trim().length >= 2;

  useEffect(() => {
    ultimoDigitado = query;
  }, [query]);

  // Uma consulta por confirmação, não por tecla: com 54 mil títulos, consultar a
  // cada letra enfileirava uma varredura por tecla no IndexedDB e a tela ficava
  // exibindo o resultado de um termo antigo.
  useEffect(() => {
    if (!active) return;
    let cancelled = false;
    void rt
      .search(listId)
      .query(termo, { limit: 120 })
      .then((h) => {
        if (cancelled) return;
        setRawHits(h);
        setBuscando(false);
        ultimoBuscado = termo;
        ultimosHits = h;
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setBuscando(false); // senão o "Buscando…" fica para sempre
        rt.logger.warn('falha na busca', { err: String(err) });
      });
    return () => {
      cancelled = true;
    };
  }, [rt, listId, termo, active]);

  const buscar = () => {
    const novo = query.trim();
    if (novo === termo) return; // mesma busca: os resultados já estão na tela
    setBuscando(novo.length >= 2);
    setTermo(novo);
  };

  // Enquanto o próximo termo é digitado, os resultados do anterior ficam na
  // tela: piscar para vazio a cada letra era pior que esperar.
  const hits = active ? rawHits : [];
  const groups = useMemo(
    () => ({
      vod: hits.filter((h) => h.kind === 'vod'),
      series: hits.filter((h) => h.kind === 'series'),
      live: hits.filter((h) => h.kind === 'live'),
    }),
    [hits],
  );

  const open = (h: SearchHit) => {
    if (h.kind === 'vod') push({ name: 'movieDetail', params: { id: h.id } });
    else if (h.kind === 'series') push({ name: 'seriesDetail', params: { id: h.id } });
    else
      push({ name: 'player', params: { kind: 'live', streamId: h.id, title: h.name } });
  };

  const { ref, focusKey } = useFocusable({ focusKey: 'search', trackChildren: true });

  return (
    <FocusContext.Provider value={focusKey}>
      <div ref={ref} className={gapRowClass} style={{ display: 'flex', ...gapVar('2rem') }}>
        {/* Coluna do teclado: em viewport baixo o título e o campo comiam a
            altura que faltava para as últimas linhas de teclas caberem. */}
        <div style={{ flexShrink: 0 }}>
          <h1 style={{ fontSize: cssLen('min(var(--fs-title), 5vh)'), margin: '0 0 0.3em' }}>
            {t('search.title')}
          </h1>
          <p
            style={{
              fontSize: cssLen('min(var(--fs-section), 4.5vh)'),
              minHeight: '1.5em',
              margin: '0 0 0.5em',
            }}
          >
            {query || t('search.placeholder')}
          </p>
          <OnScreenKeyboard
            focusKey="search-kb"
            onInput={(ch) => setQuery((q) => q + ch)}
            onDelete={() => setQuery((q) => q.slice(0, -1))}
            onClear={() => {
              setQuery('');
              setTermo('');
            }}
            onSubmit={buscar}
          />
        </div>

        <div
          style={{
            flex: 1,
            minHeight: 0, // ver a nota em `Catalog.tsx`
            // `min-width: auto` (padrão do item flex) deixa esta coluna crescer
            // até a largura *intrínseca* da trilha lá dentro — que é a lista
            // inteira lado a lado. Medido no aparelho: a coluna ia a 19.173.960px
            // e cada cartão a 2.739.123px, num laço com o ResizeObserver.
            minWidth: 0,
            display: 'flex',
            flexDirection: 'column',
            ...gapVar('var(--row-gap)'),
          }}
          className={gapColClass}
        >
          {hits.length === 0 ? (
            <EmptyState
              loading={buscando}
              body={buscando ? t('search.searching') : t('search.empty')}
            />
          ) : (
            <>
              <div
                className={gapRowClass}
                style={{ display: 'flex', alignItems: 'center', ...gapVar('0.8rem') }}
              >
                <span style={{ color: 'var(--text-secondary)', flexShrink: 0 }}>
                  {buscando
                    ? t('search.searching')
                    : t('search.resultCount', { n: hits.length })}
                </span>
                {/* Abas por tipo (tela 08). Só aparecem as que têm resultado —
                    uma aba vazia é um beco sem saída para o D-pad. */}
                <GenreChips
                  focusKey="search-abas"
                  selectedId={aba}
                  onSelect={(id) => setAba(id as typeof aba)}
                  chips={[
                    { id: 'todos', label: t('favorites.tabAll') },
                    ...(groups.vod.length
                      ? [{ id: 'vod', label: t('search.groupMovies') }]
                      : []),
                    ...(groups.series.length
                      ? [{ id: 'series', label: t('search.groupSeries') }]
                      : []),
                    ...(groups.live.length
                      ? [{ id: 'live', label: t('search.groupChannels') }]
                      : []),
                  ]}
                />
              </div>
              {(aba === 'todos' || aba === 'vod') && (
                <Group
                  label={t('search.groupMovies')}
                  rows={groups.vod}
                  fk="sr-vod"
                  termo={termo}
                  onOpen={open}
                />
              )}
              {(aba === 'todos' || aba === 'series') && (
                <Group
                  label={t('search.groupSeries')}
                  rows={groups.series}
                  fk="sr-series"
                  termo={termo}
                  onOpen={open}
                />
              )}
              {(aba === 'todos' || aba === 'live') && (
                <Group
                  label={t('search.groupChannels')}
                  rows={groups.live}
                  fk="sr-live"
                  termo={termo}
                  onOpen={open}
                />
              )}
            </>
          )}
        </div>
      </div>
    </FocusContext.Provider>
  );
}

function Group({
  label,
  rows,
  fk,
  termo,
  onOpen,
}: {
  label: string;
  rows: SearchHit[];
  fk: string;
  termo: string;
  onOpen: (h: SearchHit) => void;
}) {
  const rem = useRemPx();
  if (rows.length === 0) return null;
  return (
    <section>
      <h3 style={{ fontSize: 'var(--fs-section)' }}>
        {label} ({rows.length})
      </h3>
      <VirtualRow
        focusKey={fk}
        restoreKey={`${fk}:${termo}`}
        items={rows}
        // a coluna de resultados divide a tela com o teclado: um número fixo de
        // cartões daria 40px cada no telefone deitado. 8rem acompanha a escala
        // da raiz (13px no telefone, ~25px na TV).
        minItemWidth={rem * 8}
        renderItem={(h, _i, focused) => (
          <PosterCard focused={focused} data={{ title: h.name, poster: h.poster }} />
        )}
        onItemPress={onOpen}
      />
    </section>
  );
}
